static lstr L9144 = {-1, 1133, "// std/build: the target a program is built for. The compiler sets os, arch and\012// debug for each build; the values written here are replaced. An `if` that\012// tests only these constants keeps one branch in the output.\012\012import * as Host from \"std/internal/host\"\012\012export enum Os derives Show, Equatable {\012  MacOS\012  Linux\012  Windows\012}\012\012export enum Arch derives Show, Equatable {\012  Arm64\012  X86_64\012}\012\012export const os: Os = Os.Linux\012export const arch: Arch = Arch.X86_64\012export const debug: bool = true\012\012export struct Target {\012  os: Os\012  arch: Arch\012}\012\012export function hostTarget(): Option<Target> {\012  const hostOs = Host.os()\012  const hostArch = Host.arch()\012  // The C compiler's predefined macros give the codes; 0 is a machine with no variant here.\012  if (hostOs == 0 || hostArch == 0) {\012    return None\012  }\012  if (hostOs == 1 && hostArch == 1) {\012    return Some(Target { os: Os.MacOS, arch: Arch.Arm64 })\012  }\012  if (hostOs == 1) {\012    return Some(Target { os: Os.MacOS, arch: Arch.X86_64 })\012  }\012  if (hostArch == 1) {\012    return Some(Target { os: Os.Linux, arch: Arch.Arm64 })\012  }\012  return Some(Target { os: Os.Linux, arch: Arch.X86_64 })\012}\012"};
static lstr L9145 = {-1, 8, "std/cell"};
static lstr L9146 = {-1, 870, "// std/cell: Cell<T>, one mutable slot that every copy of the handle shares.\012//\012// A Cell is an identity type: copying it, capturing it in a closure or storing it in a\012// struct copies the handle, and Cell.set through any copy changes what all of them read.\012\012import * as Boxes from \"std/box\"\012import * as Slot from \"std/internal/cell\"\012\012export opaque struct Cell<T> {\012  slot: Box<T>\012}\012\012export function create<T>(value: T): Cell<T> uses alloc {\012  return Cell { slot: Boxes.new(value) }\012}\012\012export function get<T>(cell: Cell<T>): T from cell {\012  return cell.slot.value\012}\012\012export function set<T>(cell: Cell<T>, value: T) {\012  Slot.store(cell.slot, value)\012}\012\012export function update<T, effect E>(cell: Cell<T>, change: (value: T) => T uses E) uses E {\012  // Hold the old value, so a set inside change cannot free it.\012  const old = get(cell)\012  Slot.store(cell.slot, change(old))\012}\012"};
