static lstr L9150 = {-1, 1182, "// std/cstring: CString, a string with no zero byte, which C reads as a zero-terminated string.\012//\012// Pass `CStrings.pointer(text)` to a C function that takes `char*`; the pointer is valid while\012// the CString is. `CStrings.read` copies a zero-terminated string that C returns.\012\012import * as Bytes from \"std/bytes\"\012import * as Str from \"std/string\"\012import * as Ptr from \"std/ptr\"\012import * as Text from \"std/internal/cstring\"\012\012export opaque struct CString {\012  text: string\012}\012\012export function from(text: string): Option<CString> {\012  // C would stop at a zero byte, so a string that holds one has no CString.\012  const length = Str.length(text)\012  for (let index = 0; index < length; index++) {\012    if (Str.byteAt(text, index) == 0) {\012      return None\012    }\012  }\012  return Some(CString { text: text })\012}\012\012export function toString(value: CString): string from value {\012  return value.text\012}\012\012export function pointer(value: CString): Ptr<u8> {\012  return Text.pointer(value.text)\012}\012\012export function read(address: Ptr<u8>): Result<string, string> uses alloc, unsafe {\012  let copied: Result<string, string> = Err(\"\")\012  unsafe {\012    copied = Bytes.toString(Text.read(address))\012  }\012  return copied\012}\012"};
static lstr L9151 = {-1, 13, "std/ext/array"};
static lstr L9152 = {-1, 833, "// std/array: helpers over Array. The functions that need the compiler are built in.\012\012import * as Arrays from \"std/array\"\012\012export function map<T, U, effect E>(\012  items: Array<T>,\012  change: (value: T) => U uses E\012): Array<U> uses alloc, E {\012  let result: Array<U> = Arrays.withCapacity(Arrays.length(items))\012  for (const item of items) {\012    Arrays.push(mutable result, change(item))\012  }\012  return result\012}\012\012export function slice<T>(items: Array<T>, start: int, finish: int): Option<Array<T>> uses alloc {\012  // A range outside the array has no slice.\012  if (start < 0 || finish > Arrays.length(items) || start > finish) {\012    return None\012  }\012  let result: Array<T> = Arrays.withCapacity(finish - start)\012  for (let index = start; index < finish; index++) {\012    Arrays.push(mutable result, copy(items[index]))\012  }\012  return Some(result)\012}\012"};
