static lstr L9156 = {-1, 915, "// std/int: ordering and division of int. The rest of the functions are built into the compiler.\012\012export function compare(first: int, second: int): Ordering {\012  if (first < second) {\012    return Ordering.Less\012  }\012  if (first > second) {\012    return Ordering.Greater\012  }\012  return Ordering.Equal\012}\012\012export function divmod(dividend: int, divisor: int): Option<#[int, int]> {\012  // A zero divisor has no quotient.\012  if (divisor == 0) {\012    return None\012  }\012  return Some(#[dividend / divisor, dividend % divisor])\012}\012\012export function floorDiv(dividend: int, divisor: int): Option<int> {\012  if (divisor == 0) {\012    return None\012  }\012  const quotient = dividend / divisor\012  const remainder = dividend % divisor\012  // Division truncates toward zero; step down when the signs differ and the division is inexact.\012  if (remainder != 0 && (remainder < 0) != (divisor < 0)) {\012    return Some(quotient - 1)\012  }\012  return Some(quotient)\012}\012"};
