static lstr L9164 = {-1, 148783, "// std/internal/unicode: the Unicode 17.0.0 tables of std/unicode.\012// Generated by scripts/unicode/generate.nra from the Unicode Character Database. Do not edit.\012// Source: https://www.unicode.org/Public/17.0.0/ucd/ (auxiliary/ and emoji/ files flat).\012//\012// Inputs (SHA-256):\012//   UnicodeData.txt 2e1efc1dcb59c575eedf5ccae60f95229f706ee6d031835247d843c11d96470c\012//   SpecialCasing.txt efc25faf19de21b92c1194c111c932e03d2a5eaf18194e33f1156e96de4c9588\012//   CaseFolding.txt ff8d8fefbf123574205085d6714c36149eb946d717a0c585c27f0f4ef58c4183\012//   GraphemeBreakProperty.txt d6b51d1d2ae5c33b451b7ed994b48f1f4dc62b2272a5831e7fd418514a6bae89\012//   emoji-data.txt 2cb2bb9455cda83e8481541ecf5b6dfda66a3bb89efa3fa7c5297eccf607b72b\012//   EastAsianWidth.txt ea7ce50f3444a050333448dffef1cadd9325af55cbb764b4a2280faf52170a33\012//   DerivedCoreProperties.txt 24c7fed1195c482faaefd5c1e7eb821c5ee1fb6de07ecdbaa64b56a99da22c08\012//   CompositionExclusions.txt 2f239196ef3b5b61db5cc476e9bd80f534d15aa1b74e1be1dea5d042a344c85f\012//   DerivedNormalizationProps.txt 71fd6a206a2c0cdd41feb6b7f656aa31091db45e9cedc926985d718397f9e488\012//\012// Numbers are lowercase hex. A range record is start (6), end (6) and a value.\012\012export const VERSION = \"17.0.0\"\012\012// Grapheme properties (14): range, then 2 digits: Grapheme_Cluster_Break (0 Other, 1 CR, 2 LF, 3 Control, 4 Extend, 5 ZWJ, 6 Regional_Indicator, 7 Prepend, 8 SpacingMark, 9 L, 10 V, 11 T, 12 LV, 13 LVT) + 16 * Indic_Conjunct_Break (1 Consonant, 2 Extend, 3 Linker) + 64 * Extended_Pictographic.\012export const GRAPHEME = \"\"\012\012// Display width (13): range, then 1 digit: 0 zero width, 1 an emoji with text presentation (2 columns with U+FE0F), 2 wide. Any other code point is 1 column.\012export const WIDTH = \"\"\012\012// Case context (13): range, then 1 digit: 1 Cased, 2 Case_Ignorable, 3 both.\012export const CASE_CONTEXT = \"\"\012\012// Case mapping ranges (19): range, stride (1 digit), target of the start (6). A code point start + stride * k maps to target + stride * k.\012export const UPPER_RANGES = \"\"\012export const LOWER_RANGES = \"\"\012export const FOLD_RANGES = \"\"\012\012// Full case mappings (24): code point (6), then three targets (6 each), 000000 for none.\012export const UPPER_FULL = \"\"\012export const LOWER_FULL = \"000130000069000307000000\"\012export const FOLD_FULL = \"\"\012\012// Normalization properties (14): start (5), end (5), then 4 digits: Canonical_Combining_Class + 256 * quick check (1 NFD_QC=N, 2 NFKD_QC=N, 4 NFC_QC=N, 8 NFC_QC=M, 16 NFKC_QC=N, 32 NFKC_QC=M). Any other code point is class 0 and Yes in every quick check.\012export const NORMAL_PROPERTIES = \"\"\012\012// Canonical decompositions (15), one step: code point (5), then one or two code points (5 each), 00000 for none.\012export const CANONICAL = \"\"\012\012// Canonical composition (3): the index of each two code point CANONICAL record that composes (not Full_Composition_Exclusion), sorted by its first and then its second code point.\012export const COMPOSITION = \"\"\012\012// Compatibility decompositions to one code point (15), one step: start (5), end (5), target of the start (5). A code point start + k decomposes to target + k.\012export const COMPATIBILITY_RANGES = \"\"\012\012// Longer compatibility decompositions (9), one step: code point (5), then the offset (4) of its first code point in COMPATIBILITY_DATA, counted in code points. The next record's offset, or the end of the data, ends it.\012export const COMPATIBILITY = \"\"\012\012// The code points of COMPATIBILITY (5 each).\012export const COMPATIBILITY_DATA = \"\"\012"};
